INSERT INTO projects (id, name, investor, location, description, total_units, status, created_at) VALUES ('455945df-91ce-48b4-9ae8-6e967ea7abde', 'Sunny Line', 'Sunny Line DOO', 'Klisa, Novi Sad', 'SUNNY LINE - jedinstven stambeni kompleks koji se sastoji od 3 nezavisne ville na prestižnoj lokaciji Klise, u Ulici Đakona Avakuma. Svaka vila je nezavisan objekat. Ukupno 16 stanova različitih veličina. Modern arhitektonski pristup. Miran deo grada okružen zelenilom. Odlična povezanost sa centrom grada. Planiran završetak: maj 2027 (±60 dana). Početak gradnje: maj 2026.', 16, 'U izgradnji', '2026-06-02T11:09:45.550Z');
